import { DescriptionListCard } from '@gntik-ai/blocks';
import { Heading, Link, LiveAnnouncer, Stack, WizardLayout, useAnnounce, useHasLiveAnnouncer } from '@gntik-ai/ui';
import { useEffect, useEffectEvent, useId, useLayoutEffect, useRef, useState } from 'react';
import { useSubmitState } from './useSubmitState';
import type { CreateWizardFlowProps } from './flow-types';
export type {
  CreateWizardFlowProps,
  CreateWizardFlowLabels,
  CreateWizardFlowStep,
  CreateWizardFieldErrors,
  CreateWizardSubmitState,
} from './flow-types';

/** Additive caller-defined flow; the legacy page retains its original props and defaults. */
export function CreateWizardFlow<V extends object>(props: CreateWizardFlowProps<V>) {
  return useHasLiveAnnouncer() ? (
    <Flow {...props} />
  ) : (
    <LiveAnnouncer>
      <Flow {...props} />
    </LiveAnnouncer>
  );
}

function Flow<V extends object>(props: CreateWizardFlowProps<V>) {
  const { flowSteps, initialValues, summary, labels, onExit } = props;
  const { state, finish, reset, successText, errorText } = useSubmitState(props);
  const id = useId();
  const announce = useAnnounce();
  const focused = useRef<HTMLElement | null>(null);
  const [step, setStep] = useState(() =>
    props.submitState && props.submitState.status !== 'idle' ? flowSteps.length : 0,
  );
  const [values, setValues] = useState(initialValues);
  const [visited, setVisited] = useState<ReadonlySet<string>>(new Set());
  const [invalidPress, setInvalidPress] = useState(0);
  const body = useRef<HTMLElement>(null);
  const editFocus = useRef(false);
  const current = flowSteps[step];
  const validation = current?.validate?.(values);
  const fieldErrors = current?.readOnly ? {} : (validation?.fieldErrors ?? {});
  const errors = current && visited.has(current.id) ? fieldErrors : {};
  const blocking = validation?.blocking;
  const locked = state.status === 'submitting' || state.status === 'success';
  const resource = state.status === 'success' && state.result != null ? props.resourceHref?.(state.result) : undefined;
  const headingId = `${id}-heading`;
  const steps = [...flowSteps.map(({ id, label }) => ({ id, label })), { id: `${id}-review`, label: labels.review }];

  const active = props.mode !== 'overlay' || props.open === true;
  useEffect(() => {
    if (!active || !blocking) return;
    const frame = requestAnimationFrame(() => announce(blocking));
    return () => cancelAnimationFrame(frame);
  }, [active, step, blocking, announce]);
  const announceStep = useEffectEvent(() => {
    if (!blocking && (current || state.status === 'idle'))
      announce(
        labels.stepAnnouncement({
          position: step + 1,
          total: flowSteps.length + 1,
          label: current?.label ?? labels.review,
        }),
      );
  });
  useEffect(() => {
    if (!active || props.mode !== 'overlay') return;
    const frame = requestAnimationFrame(() => announceStep());
    return () => cancelAnimationFrame(frame);
  }, [active, step, props.mode]);
  useLayoutEffect(() => {
    const previous = focused.current;
    if (!active || !previous) return;
    const disabled = previous.matches(':disabled');
    const removed = !previous.isConnected;
    if ((disabled || removed) && (document.activeElement === previous || document.activeElement === document.body))
      (state.status === 'success'
        ? (body.current?.querySelector<HTMLElement>('[data-flow-success] a[href]') ??
          body.current?.querySelector<HTMLElement>('[data-flow-success] h2'))
        : body.current?.querySelector<HTMLElement>('h1')
      )?.focus();
  });
  useLayoutEffect(() => {
    if (invalidPress) body.current?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus();
  }, [invalidPress]);
  useLayoutEffect(() => {
    if (editFocus.current) {
      body.current?.querySelector<HTMLElement>('h1')?.focus();
      editFocus.current = false;
    }
  }, [step]);

  const go = (next: number) => {
    if (locked || (next > step && blocking)) return;
    if (next > step && current) setVisited((previous) => new Set([...previous, current.id]));
    if (next > step && current && Object.values(fieldErrors).some(Boolean)) {
      setInvalidPress((press) => press + 1);
      return;
    }
    setStep(next);
  };
  const rows = current ? [] : summary(values);
  return (
    <WizardLayout
      mode={props.mode}
      size={props.size}
      open={props.open}
      onOpenChange={props.onOpenChange}
      description={props.description}
      returnFocusRef={props.returnFocusRef}
      closeOnInteractOutside={props.closeOnInteractOutside}
      confirmExit={props.confirmExit}
      fullScreen
      title={labels.title}
      steps={steps}
      current={step}
      onFocusCapture={(event) => {
        if (event.target instanceof HTMLElement) focused.current = event.target;
      }}
      onStepChange={go}
      stepsInteractive={false}
      nextDisabled={Boolean(blocking) || state.status === 'success'}
      backDisabled={locked}
      onExit={() => {
        reset();
        setValues(initialValues);
        setStep(0);
        setVisited(new Set());
        setInvalidPress(0);
        onExit();
      }}
      onFinish={() => void finish(values)}
      nextLoading={state.status === 'submitting'}
      exitLabel={labels.exit}
      backLabel={labels.back}
      nextLabel={labels.next}
      finishLabel={state.status === 'submitting' ? labels.pending : labels.finish}
      pendingLabel={labels.pending}
      cancelLabel={labels.cancel}
      stepsLabel={labels.steps}
      stepsSummaryLabel={labels.stepsSummary}
      skipLinkLabel={labels.skipLink}
      stepStatusText={labels.stepStatusText}
      formatStepCount={labels.formatStepCount}
      stepAnnouncement={() => ''}
      exitTitle={labels.exitTitle}
      exitDescription={labels.exitDescription}
      exitConfirmLabel={labels.exitConfirm}
      exitCancelLabel={labels.exitCancel}
    >
      <section ref={body} aria-labelledby={headingId}>
        <Stack gap={6}>
          <Heading level={1} id={headingId} tabIndex={-1} size="lg">
            {current?.label ?? labels.reviewTitle}
          </Heading>
          {current
            ? current.render({
                values,
                setValue: (key, value) => setValues((previous) => ({ ...previous, [key]: value })),
                errors,
              })
            : flowSteps.map((source, index) => (
                <DescriptionListCard
                  key={source.id}
                  titleAs="h2"
                  title={source.label}
                  description=""
                  editLabel={labels.edit(source.label)}
                  onEdit={
                    locked
                      ? undefined
                      : () => {
                          editFocus.current = true;
                          go(index);
                        }
                  }
                  items={rows
                    .filter((row) => row.stepId === source.id)
                    .map((row, rowIndex) => ({
                      id: `${source.id}-${rowIndex}`,
                      label: row.label,
                      value: row.value || labels.emptyValue,
                    }))}
                />
              ))}
          {state.status === 'error' && <p className="text-destructive-text">{errorText}</p>}
          {state.status === 'success' && (
            <div data-flow-success>
              <Heading level={2} tabIndex={-1}>
                {successText}
              </Heading>
              {resource && <Link href={resource}>{labels.openResource}</Link>}
            </div>
          )}
          {blocking && <p className="text-destructive-text">{blocking}</p>}
        </Stack>
      </section>
    </WizardLayout>
  );
}

import { CreateWizardFlow, type CreateWizardFlowProps } from './Flow';
import { DescriptionListCard } from '@gntik-ai/blocks';
import {
  Checkbox,
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
  Heading,
  Input,
  Logo,
  SelectableCard,
  SelectableCardGroup,
  SimpleSelect,
  Stack,
  Text,
  Textarea,
  WizardLayout,
  type StepItem,
  type WizardLayoutProps,
} from '@gntik-ai/ui';
import { useId, useState, type ReactNode, type ReactElement } from 'react';
import {
  PROJECT_NAME_RE,
  wizardCopy,
  wizardInitialValues,
  wizardRegions,
  wizardSources,
  wizardSteps,
  type CreateWizardCopy,
  type SourceOption,
  type WizardRegion,
  type WizardValues,
} from './data';

export interface CreateWizardProps extends Pick<
  WizardLayoutProps,
  | 'mode'
  | 'size'
  | 'open'
  | 'onOpenChange'
  | 'description'
  | 'returnFocusRef'
  | 'closeOnInteractOutside'
  | 'stepAnnouncement'
  | 'pendingLabel'
> {
  /** Step-local errors or empty states, rendered within the scrollable step body. */
  stepFeedback?: (current: number) => ReactNode;
  /** Flow name in the top bar. */
  title: string;
  steps: StepItem[];
  initialValues: WizardValues;
  sources: readonly SourceOption[];
  regions: readonly WizardRegion[];
  /** Called from the review step; return a promise to show the loading state. */
  onFinish: (values: WizardValues) => void | Promise<void>;
  /** Called after the exit is confirmed. */
  onExit: () => void;
  onStepChange: (index: number) => void;
  /** Step titles, field labels, submit label…; unset keys keep the default (project) wording. */
  copy: Partial<CreateWizardCopy>;
}

function StepIntro({ id, title, children }: { id: string; title: string; children?: ReactNode }) {
  return (
    <Stack gap={1}>
      <Heading level={1} id={id} size="lg">
        {title}
      </Heading>
      {children && <Text variant="supporting">{children}</Text>}
    </Stack>
  );
}

/** Multi-step create flow in the focus-mode WizardLayout, ending in a review of every answer. */
function LegacyCreateWizardPage({
  title = 'New project',
  steps = wizardSteps,
  initialValues = wizardInitialValues,
  sources = wizardSources,
  regions = wizardRegions,
  onFinish,
  onExit,
  onStepChange,
  copy: copyOverrides,
  stepFeedback,
  ...presentation
}: Partial<CreateWizardProps>) {
  const copy: CreateWizardCopy = { ...wizardCopy, ...copyOverrides };
  const id = useId();
  const [step, setStep] = useState(0);
  const [values, setValues] = useState(initialValues);
  const [touched, setTouched] = useState(false);
  const [finishing, setFinishing] = useState(false);
  const [status, setStatus] = useState('');
  const set = <K extends keyof WizardValues>(key: K, value: WizardValues[K]) =>
    setValues((v) => ({ ...v, [key]: value }));

  const nameValid = PROJECT_NAME_RE.test(values.name);
  const nameError = touched && !nameValid ? (values.name ? copy.nameInvalid : copy.nameRequired) : undefined;
  const go = (index: number) => {
    setStep(index);
    onStepChange?.(index);
  };
  const sourceLabel = sources.find((s) => s.value === values.source)?.title ?? values.source;
  const regionLabel = regions.find((r) => r.value === values.region)?.label ?? values.region;

  const finish = async () => {
    setFinishing(true);
    try {
      await onFinish?.(values);
      setStatus(copy.created(values.name));
    } finally {
      setFinishing(false);
    }
  };

  return (
    <WizardLayout
      {...presentation}
      fullScreen
      logo={<Logo size={22} />}
      title={title}
      steps={steps}
      current={step}
      onStepChange={go}
      nextDisabled={step === 0 && !nameValid}
      nextLoading={finishing}
      finishLabel={copy.submitLabel}
      onFinish={() => void finish()}
      onExit={onExit}
      exitTitle={copy.exitTitle}
      exitDescription={copy.exitDescription}
      footerStart={<span aria-live="polite">{status}</span>}
    >
      {stepFeedback?.(step)}
      {step === 0 && (
        <section aria-labelledby={`${id}-details`}>
          <Stack gap={6}>
            <StepIntro id={`${id}-details`} title={copy.detailsTitle}>
              {copy.detailsIntro}
            </StepIntro>
            <Field invalid={nameError != null}>
              <FieldLabel required>{copy.nameLabel}</FieldLabel>
              <Input
                required
                value={values.name}
                onValueChange={(v) => set('name', v)}
                onBlur={() => setTouched(true)}
                placeholder={copy.namePlaceholder}
              />
              <FieldDescription>{copy.nameHint}</FieldDescription>
              <FieldError match={nameError != null}>{nameError}</FieldError>
            </Field>
            <Field>
              <FieldLabel>{copy.descriptionLabel}</FieldLabel>
              <Textarea rows={3} value={values.description} onValueChange={(v) => set('description', v)} />
            </Field>
          </Stack>
        </section>
      )}
      {step === 1 && (
        <section aria-labelledby={`${id}-source`}>
          <Stack gap={6}>
            <StepIntro id={`${id}-source`} title={copy.sourceTitle}>
              {copy.sourceIntro}
            </StepIntro>
            <SelectableCardGroup
              aria-labelledby={`${id}-source`}
              value={values.source}
              onValueChange={(v) => set('source', v)}
              columns={1}
            >
              {sources.map((s) => {
                const Icon = s.icon;
                return (
                  <SelectableCard
                    key={s.value}
                    value={s.value}
                    title={s.title}
                    description={s.description}
                    icon={<Icon size={18} aria-hidden />}
                  />
                );
              })}
            </SelectableCardGroup>
          </Stack>
        </section>
      )}
      {step === 2 && (
        <section aria-labelledby={`${id}-configure`}>
          <Stack gap={6}>
            <StepIntro id={`${id}-configure`} title={copy.configureTitle}>
              {copy.configureIntro}
            </StepIntro>
            <SimpleSelect
              label={copy.regionLabel}
              items={regions}
              value={values.region}
              onValueChange={(v) => v && set('region', v)}
              className="w-full"
            />
            <Checkbox
              label={copy.previewsLabel}
              description={copy.previewsDescription}
              checked={values.previews}
              onCheckedChange={(checked) => set('previews', checked)}
            />
          </Stack>
        </section>
      )}
      {step === 3 && (
        <section aria-labelledby={`${id}-review`}>
          <Stack gap={6}>
            <StepIntro id={`${id}-review`} title={copy.reviewTitle}>
              {copy.reviewIntro}
            </StepIntro>
            <DescriptionListCard
              titleAs="h2"
              title={copy.reviewDetailsTitle}
              description={copy.reviewDetailsDescription}
              items={[
                { id: 'name', label: copy.nameLabel, value: values.name, mono: true },
                { id: 'description', label: copy.descriptionLabel, value: values.description || '—' },
              ]}
              onEdit={() => go(0)}
              editLabel={copy.editDetailsLabel}
            />
            <DescriptionListCard
              titleAs="h2"
              title={copy.reviewSourceTitle}
              description={copy.reviewSourceDescription}
              items={[
                { id: 'source', label: copy.sourceLabel, value: sourceLabel },
                { id: 'region', label: copy.regionLabel, value: regionLabel },
                { id: 'previews', label: copy.previewsLabel, value: values.previews ? copy.on : copy.off },
              ]}
              onEdit={() => go(1)}
              editLabel={copy.editSourceLabel}
            />
          </Stack>
        </section>
      )}
    </WizardLayout>
  );
}

/** flowSteps selects the additive variant; legacy props cannot be combined with it. */
export default function CreateWizardPage(
  props: Partial<CreateWizardProps> & {
    flowSteps?: never;
    labels?: never;
    summary?: never;
    submitState?: never;
    onComplete?: never;
    resourceHref?: never;
    errorMessage?: never;
  },
): ReactElement;
export default function CreateWizardPage<V extends object>(props: CreateWizardFlowProps<V>): ReactElement;
export default function CreateWizardPage<V extends object>(
  props:
    | CreateWizardFlowProps<V>
    | (Partial<CreateWizardProps> & {
        flowSteps?: never;
        labels?: never;
        summary?: never;
        submitState?: never;
        onComplete?: never;
        resourceHref?: never;
        errorMessage?: never;
      }),
) {
  if (props.flowSteps !== undefined) return <CreateWizardFlow {...props} />;
  return <LegacyCreateWizardPage {...props} />;
}

