  summaryHeading?: string;
  reviewDetailsTitle: string;
  reviewDetailsDescription: string;
  editDetailsLabel: string;
  reviewSourceTitle: string;
  reviewSourceDescription: string;
  editSourceLabel: string;
  sourceLabel: string;
  on: string;
  off: string;
