import type { ReactNode } from 'react';
import type { StepStatus, WizardLayoutProps } from '@gntik-ai/ui';

export type CreateWizardFieldErrors<V> = Partial<Record<keyof V, string>>;
export interface CreateWizardFlowStep<V> {
  id: string;
  label: string;
  /** Render fixed values as text. Field errors are ignored on a read-only step. */
  readOnly?: boolean;
  render: (context: {
    values: V;
    setValue: <K extends keyof V>(key: K, value: V[K]) => void;
    errors: CreateWizardFieldErrors<V>;
  }) => ReactNode;
  /** Pure validation, evaluated on every render, including caller re-renders. */
  validate?: (values: V) => { fieldErrors?: CreateWizardFieldErrors<V>; blocking?: string };
}

export interface CreateWizardFlowLabels {
  title: string;
  exit: string;
  cancel: string;
  back: string;
  next: string;
  finish: string;
  pending: string;
  review: string;
  reviewTitle: string;
  edit: (stepLabel: string) => string;
  emptyValue: string;
  success: (result: unknown) => string;
  errorFallback: string;
  openResource: string;
  exitTitle: string;
  exitDescription: string;
  exitConfirm: string;
  exitCancel: string;
  steps: string;
  stepsSummary: string;
  stepStatusText: Record<StepStatus, string>;
  formatStepCount: (position: number, total: number) => string;
  stepAnnouncement: (step: { position: number; total: number; label: ReactNode }) => string;
  skipLink: string;
}

export type CreateWizardSubmitState =
  | { status: 'idle' }
  | { status: 'submitting' }
  | { status: 'success'; result?: unknown }
  | { status: 'error'; error?: unknown; message?: string };

export interface CreateWizardFlowProps<V extends object> extends Pick<
  WizardLayoutProps,
  | 'mode'
  | 'size'
  | 'open'
  | 'onOpenChange'
  | 'description'
  | 'returnFocusRef'
  | 'closeOnInteractOutside'
  | 'confirmExit'
> {
  flowSteps: readonly CreateWizardFlowStep<V>[];
  initialValues: V;
  summary: (values: V) => readonly { stepId: string; label: string; value?: string | null }[];
  labels: CreateWizardFlowLabels;
  onFinish: (values: V, context: { signal: AbortSignal }) => void | Promise<unknown>;
  onExit: () => void;
  onComplete?: (result: unknown) => void;
  /** Mode is fixed at mount. Controlled callers discard aborted completions and reset to idle on exit. */
  submitState?: CreateWizardSubmitState;
  resourceHref?: (result: unknown) => string | undefined;
  errorMessage?: (error: unknown) => string | undefined;
  /** Legacy-only props cannot mix with flow mode. */
  copy?: never;
  steps?: never;
  sources?: never;
  regions?: never;
  title?: never;
  onStepChange?: never;
  stepFeedback?: never;
  pendingLabel?: never;
  stepAnnouncement?: never;
}

import { useAnnounce } from '@gntik-ai/ui';
import { useEffect, useEffectEvent, useRef, useState } from 'react';
import type { CreateWizardFlowProps, CreateWizardSubmitState } from './flow-types';

const IDLE: CreateWizardSubmitState = { status: 'idle' };

/** Owns attempts, never transport; controlled callers own all settled state. */
export function useSubmitState<V extends object>(props: CreateWizardFlowProps<V>) {
  const [controlled] = useState(() => props.submitState !== undefined);
  const [internal, setInternal] = useState<CreateWizardSubmitState>({ status: 'idle' });
  const attempt = useRef<AbortController | null>(null);
  const state = controlled ? (props.submitState ?? IDLE) : internal;
  const announce = useAnnounce();
  const previous = useRef(state.status);
  const lastError = useRef('');
  const complete = useEffectEvent((result: unknown) => props.onComplete?.(result));
  const errorText =
    state.status === 'error' ? state.message || props.errorMessage?.(state.error) || props.labels.errorFallback : '';
  const successText = state.status === 'success' ? props.labels.success(state.result) : '';

  useEffect(
    () => () => {
      attempt.current?.abort();
    },
    [],
  );
  useEffect(() => {
    const was = previous.current;
    previous.current = state.status;
    if (state.status === 'error' && (was === 'submitting' || (was === 'error' && lastError.current !== errorText)))
      announce(errorText, 'assertive');
    lastError.current = errorText;
    if (state.status !== 'success' || was !== 'submitting') return;
    const controller = attempt.current;
    announce(successText);
    if (!controlled && controller) {
      // The page-level region commits before a closing callback can unmount the wizard.
      requestAnimationFrame(() => {
        if (!controller.signal.aborted && attempt.current === controller) complete(state.result);
      });
    }
  }, [state, successText, errorText, announce, controlled]);

  const finish = async (values: V) => {
    if (state.status === 'submitting' || state.status === 'success') return;
    attempt.current?.abort();
    const controller = new AbortController();
    attempt.current = controller;
    if (!controlled) {
      previous.current = 'submitting';
      setInternal({ status: 'submitting' });
    }
    try {
      const result = await props.onFinish(values, { signal: controller.signal });
      if (!controlled && !controller.signal.aborted) setInternal({ status: 'success', result });
    } catch (error: unknown) {
      if (!controlled && !controller.signal.aborted) setInternal({ status: 'error', error });
    }
  };
  const reset = () => {
    attempt.current?.abort();
    attempt.current = null;
    previous.current = 'idle';
    if (!controlled) setInternal({ status: 'idle' });
  };
  return { state, finish, reset, successText, errorText };
}
